import {el} from './dom.js';import {t} from './locales.js';import {saleValue,recoveryAvailable} from './engine.js';
import {CROP_IDS,CROPS,WATER,PUMP,ORDERS} from './config.js';
/** @typedef {(type:import('./engine.js').CommandType,extra?:Partial<import('./engine.js').Command>)=>void} Send */
export function setupMarket(){const dialog=/** @type {HTMLDialogElement} */(el('market-dialog'));el('market-open').addEventListener('click',()=>dialog.showModal());el('close-market').addEventListener('click',()=>dialog.close());document.addEventListener('marketopen',()=>dialog.showModal());}
/** @param {import('./engine.js').State} state @param {Send} send */
export function renderMarket(state,send){const host=el('market-lots');host.replaceChildren();if(!state.inventory.length){const text=document.createElement('p');text.className='empty-market';text.textContent=t('noProduce');host.append(text);}for(const lot of state.inventory){const row=document.createElement('div');row.className='market-lot';const label=document.createElement('span');label.textContent=t(lot.type)+' ×'+lot.quantity+' · '+Math.round(lot.quality*100)+'% '+t('quality');const button=document.createElement('button');button.type='button';button.className='action-button primary';button.dataset.sell=String(lot.id);button.textContent=t('sell')+' · +'+saleValue(lot)+' '+t('coins');button.addEventListener('click',()=>send('sell',{lot:lot.id}));row.append(label,button);host.append(row);}}
/** @param {import('./engine.js').State} state @param {Send} send */
export function renderShop(state,send){
 const shop=el('market-shop');shop.replaceChildren();const heading=document.createElement('h3');heading.textContent=t('farmSupplies');shop.append(heading);
 for(const crop of CROP_IDS){const row=document.createElement('div');row.className='market-lot';const text=document.createElement('span');text.textContent=t(crop)+' · '+state.seeds[crop]+' '+t('seeds');const b=document.createElement('button');b.type='button';b.className='action-button';b.dataset.buySeed=crop;b.textContent=t('buySeed')+' · '+CROPS[crop].seedPrice+' '+t('coins');b.addEventListener('click',()=>send('buySeed',{crop}));row.append(text,b);shop.append(row);}
 const refill=document.createElement('button');refill.id='refill';refill.type='button';refill.className='action-button';refill.textContent=t('refill')+' · ≤'+WATER.refillLitres+' L / '+WATER.refillCost+' '+t('coins');refill.addEventListener('click',()=>send('refill'));shop.append(refill);
 const aid=document.createElement('button');aid.id='recovery';aid.type='button';aid.className='action-button recovery';aid.textContent=t('recoverySeed');aid.disabled=!recoveryAvailable(state);aid.title=t('recoveryDescription');aid.addEventListener('click',()=>send('recovery'));shop.append(aid);const aidText=document.createElement('p');aidText.className='market-note';aidText.textContent=t('recoveryDescription');shop.append(aidText);
 const upgrade=document.createElement('div');upgrade.className='pump-upgrade';const desc=document.createElement('p');desc.textContent=t('pumpDescription');const b=document.createElement('button');b.type='button';b.id=state.pump.built?'pump-toggle':'buy-pump';b.className='action-button primary';b.textContent=state.pump.built?t(state.pump.on?'turnPumpOff':'turnPumpOn'):t('buildPump')+' · '+PUMP.price+' '+t('coins');b.addEventListener('click',()=>send(state.pump.built?'togglePump':'buyPump'));upgrade.append(desc,b);if(state.pump.stopReason){const reason=document.createElement('p');reason.textContent=t(state.pump.stopReason);upgrade.append(reason);}shop.append(upgrade);
 const details=document.createElement('details');details.className='ledger';const summary=document.createElement('summary');summary.textContent=t('ledger');details.append(summary);const balance=document.createElement('p');balance.id='ledger-balance';balance.textContent=t('balance')+': '+state.coins+' '+t('coins');details.append(balance);const list=document.createElement('ol');for(const line of state.ledger.slice(-12)){const item=document.createElement('li');item.textContent=t(line.type)+' '+(line.amount>=0?'+':'')+line.amount+' '+t('coins');list.append(item);}details.append(list);shop.append(details);
}
/** @param {import('./engine.js').State} state @param {Send} send */
export function renderOrders(state,send){const host=el('market-orders');host.replaceChildren();if(state.mission.step<7)return;const title=document.createElement('h3');title.textContent=t('marketOrders');host.append(title);for(const order of ORDERS){const row=document.createElement('div');row.className='order-card';const heading=document.createElement('strong');heading.textContent=t('order_'+order.id);const needs=document.createElement('p');needs.textContent=CROP_IDS.filter(c=>order.needs[c]).map(c=>t(c)+' '+state.inventory.filter(l=>l.type===c).reduce((n,l)=>n+l.quantity,0)+'/'+order.needs[c]).join(' · ');const done=state.completedOrders.includes(order.id),available=CROP_IDS.every(c=>state.inventory.filter(l=>l.type===c).reduce((n,l)=>n+l.quantity,0)>=(order.needs[c]||0));const b=document.createElement('button');b.type='button';b.className='action-button';b.dataset.order=order.id;b.disabled=done||!available;b.textContent=done?t('completed'):t('fillOrder')+' · +'+order.bonus+' '+t('bonus');b.addEventListener('click',()=>send('order',{order:order.id}));row.append(heading,needs,b);host.append(row);}const note=document.createElement('p');note.className='market-note';note.textContent=t('orderNote');host.append(note);}
